import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Random;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int count = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (ptr >= count) {
                count = in.read(buffer, 0, buffer.length);
                if (count <= 0) return -1;
                ptr = 0;
            }
            return buffer[ptr++];
        }

        public long nextLong() throws IOException {
            byte b = read();
            while (b != -1 && b <= ' ') {
                b = read();
            }
            if (b == -1) return Long.MIN_VALUE;

            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = read();
            }

            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return neg ? -res : res;
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Node {
        long key;
        int priority;
        int size;
        int count;
        Node left;
        Node right;

        Node(long key, int priority) {
            this.key = key;
            this.priority = priority;
            this.size = 1;
            this.count = 1;
        }
    }

    private static int getSize(Node t) {
        return t == null ? 0 : t.size;
    }

    private static void update(Node t) {
        if (t != null) {
            t.size = t.count + getSize(t.left) + getSize(t.right);
        }
    }

    private static Node rotateRight(Node t) {
        Node l = t.left;
        t.left = l.right;
        l.right = t;
        update(t);
        update(l);
        return l;
    }

    private static Node rotateLeft(Node t) {
        Node r = t.right;
        t.right = r.left;
        r.left = t;
        update(t);
        update(r);
        return r;
    }

    private static Node insert(Node t, long key, int priority) {
        if (t == null) {
            return new Node(key, priority);
        }
        if (t.key == key) {
            t.count++;
            t.size++;
            return t;
        }
        if (key < t.key) {
            t.left = insert(t.left, key, priority);
            if (t.left.priority > t.priority) {
                t = rotateRight(t);
            }
        } else {
            t.right = insert(t.right, key, priority);
            if (t.right.priority > t.priority) {
                t = rotateLeft(t);
            }
        }
        update(t);
        return t;
    }

    private static int countLeq(Node t, long key) {
        if (t == null) return 0;
        if (t.key <= key) {
            return getSize(t.left) + t.count + countLeq(t.right, key);
        } else {
            return countLeq(t.left, key);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        if (n <= 0) return;

        PrintWriter out = new PrintWriter(System.out);
        Random rng = new Random(42);
        Node root = null;

        long prevP = 0;

        for (int i = 0; i < n; i++) {
            long x = sc.nextLong();
            long y = sc.nextLong();

            long xr = x + prevP;
            long yr = y + prevP;

            long distSq = xr * xr + yr * yr;

            int p = countLeq(root, distSq);
            out.println(p);

            root = insert(root, distSq, rng.nextInt());
            prevP = p;
        }

        out.flush();
    }
}
